content.content:
server {
    listen 80;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;

    location / {
        try_files $uri $uri/ /index.html;
    }
}
---entrypoint---
#!/bin/sh
set -e

alembic upgrade head
exec uvicorn app.main:create_app --factory --host 0.0.0.0 --port 8000

